[
  {
    "id": "ADR-001",
    "title": "JWT with Refresh Tokens for Stateless Auth",
    "context": "Need stateless authentication with short\u2011lived access tokens and long\u2011lived refresh tokens to support scalability and security.",
    "decision": "Implement JWT access tokens (15 min expiry) signed with RSA-256 and store refresh tokens in a secure HTTP\u2011only cookie with 7\u2011day expiry. Refresh tokens are rotated on each use and invalidated on logout.",
    "consequences": "Positive: Stateless API, reduced DB lookups, easy scaling. Negative: Requires secure cookie handling and token revocation strategy. Alternatives considered: Session cookies (stateful), opaque tokens in DB (stateful)."
  },
  {
    "id": "ADR-002",
    "title": "Redis Token Bucket for Rate Limiting",
    "context": "Requirement to limit 100 requests per minute per IP with low latency.",
    "decision": "Use Redis 7's Lua scripting to implement a token bucket algorithm per IP, storing bucket state in Redis keys. Middleware checks token count before forwarding request.",
    "consequences": "Positive: Fast, distributed, single source of truth. Negative: Requires Redis availability; slight complexity in Lua scripts. Alternatives considered: In\u2011memory bucket per pod (not shared), API gateway built\u2011in rate limiter (Nginx)."
  }
]

